import { NextResponse, type NextRequest } from 'next/server';

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  if (pathname.startsWith('/dashboard')) {
    // Check for Supabase auth cookie or pingwatch demo session
    const hasSupabaseAuth = request.cookies
      .getAll()
      .some((c) => c.name.startsWith('sb-') && c.name.endsWith('-auth-token'));
    const hasDemoAuth = request.cookies.get('pingwatch_auth')?.value === 'true';

    // Allow during development if no live supabase keys are configured
    const isDevFallback = !process.env.NEXT_PUBLIC_SUPABASE_URL ||
      process.env.NEXT_PUBLIC_SUPABASE_URL.includes('placeholder') ||
      process.env.NEXT_PUBLIC_SUPABASE_URL.includes('demo');

    // In production with live Supabase, enforce strict cookie validation
    if (!hasSupabaseAuth && !hasDemoAuth && !isDevFallback) {
      const loginUrl = new URL('/auth/login', request.url);
      loginUrl.searchParams.set('redirect', pathname);
      return NextResponse.redirect(loginUrl);
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/dashboard/:path*'],
};
